<script setup>
import {computed,ref,watch} from 'vue'
import {BookOpen,FileText,Plus,Save,Search,Trash2,X} from 'lucide-vue-next'
const props=defineProps({mode:String,documents:Array,questions:Array,busy:Boolean,message:String})
const emit=defineEmits(['close','save-document','save-questions','remove-document'])
const query=ref(''),selected=ref(''),pageIndex=ref(0),draft=ref(null),questionDrafts=ref(JSON.parse(JSON.stringify(props.questions)))
const dirty=ref(false)
const documentMode=computed(()=>props.mode==='documents')
const items=computed(()=> (documentMode.value?props.documents:questionDrafts.value).filter(item=>`${item.name||''} ${item.query||''} ${item.answer||''}`.toLowerCase().includes(query.value.toLowerCase())))
const activeQuestion=computed(()=>questionDrafts.value.find(q=>q.id===selected.value))
function choose(item){selected.value=item.id;pageIndex.value=0;if(documentMode.value)draft.value=JSON.parse(JSON.stringify(item))}
function newQuestion(){const q={id:crypto.randomUUID(),query:'',answer:'',split:'dev',complete:false,judgments:{},evidence:[]};questionDrafts.value.push(q);selected.value=q.id;dirty.value=true}
watch(()=>props.documents,()=>{if(documentMode.value){const doc=props.documents.find(d=>d.id===selected.value);if(doc)draft.value=JSON.parse(JSON.stringify(doc));else if(props.documents.length)choose(props.documents[0]);else draft.value=null}})
watch(()=>props.questions,value=>{questionDrafts.value=JSON.parse(JSON.stringify(value));dirty.value=false})
if((documentMode.value?props.documents:questionDrafts.value).length)choose((documentMode.value?props.documents:questionDrafts.value)[0])
</script>
<template>
 <Teleport to="body"><div class="gold-manager-mask"><section class="gold-manager" role="dialog" aria-modal="true" :aria-label="documentMode?'黄金文档管理':'测试集管理'">
  <header><span class="gold-manager-icon"><BookOpen v-if="documentMode" :size="24"/><FileText v-else :size="24"/></span><div><h2>{{documentMode?'黄金文档管理':'测试集与黄金问答'}}</h2><p>{{documentMode?`${documents.length} 份文档 · 可编辑各页正文`:`${questionDrafts.length} 条问题 · 开发集和测试集分组`}}</p></div><button @click="emit('close')" aria-label="关闭管理页"><X :size="22"/></button></header>
  <p v-if="message" class="gold-manager-error" role="alert">{{message}}</p><div class="gold-manager-body"><aside><div class="gold-manager-search"><Search :size="16"/><input v-model="query" placeholder="搜索名称、问题或答案"/></div><button v-if="!documentMode" class="gold-add" :disabled="busy||questionDrafts.length>=200" @click="newQuestion"><Plus :size="16"/>添加测试问题</button><button v-for="(item,index) in items" :key="item.id" class="gold-item" :class="{selected:selected===item.id}" @click="choose(item)"><small>{{index+1}} · {{documentMode?`${item.pages.length} 页`:item.split==='test'?'测试集':'开发集'}}</small><strong>{{item.name||item.query||'待填写问题'}}</strong><span v-if="!documentMode">{{item.evidence?.length||0}} 条证据 · {{item.complete?'已完整标注':'待复核'}}</span></button></aside>
  <main v-if="documentMode&&draft"><label>文档名称<input v-model="draft.name" :disabled="busy"/></label><nav><button v-for="(page,index) in draft.pages" :key="page.page" :class="{selected:pageIndex===index}" @click="pageIndex=index">第 {{page.page}} 页</button></nav><label>黄金文档正文<textarea v-model="draft.pages[pageIndex].text" :disabled="busy" rows="18"/></label><p class="gold-note">修改正文后，该文档的旧证据位置会清除并标为待复核，避免原文变化导致错误评分。</p><footer><button :disabled="busy" @click="emit('remove-document',draft)"><Trash2 :size="16"/>删除文档</button><button class="gold-primary" :disabled="busy" @click="emit('save-document',{id:draft.id,name:draft.name,pages:draft.pages})"><Save :size="16"/>保存文档</button></footer></main>
  <main v-else-if="activeQuestion"><label>分组<select v-model="activeQuestion.split" :disabled="busy" @change="dirty=true"><option value="dev">开发集 · 参数调优</option><option value="test">测试集 · 最终验证</option></select></label><label>测试问题<textarea v-model="activeQuestion.query" :disabled="busy" rows="4" @input="dirty=true"/></label><label>黄金参考答案<textarea v-model="activeQuestion.answer" :disabled="busy" rows="8" @input="dirty=true"/></label><h3>相关文档和证据</h3><p v-for="evidence in activeQuestion.evidence" :key="`${evidence.documentId}:${evidence.page}:${evidence.start}`" class="gold-evidence">{{documents.find(d=>d.id===evidence.documentId)?.name}} · 第{{evidence.page}}页<br/>{{documents.find(d=>d.id===evidence.documentId)?.pages.find(p=>p.page===evidence.page)?.text.slice(evidence.start,evidence.end)}}</p><p class="gold-note">在评测主页面可继续调整相关性等级、增加或删除精确证据。</p><footer><button :disabled="busy" @click="questionDrafts=questionDrafts.filter(q=>q.id!==selected);selected=questionDrafts[0]?.id||'';dirty=true"><Trash2 :size="16"/>删除问题</button><button class="gold-primary" :disabled="busy||!dirty" @click="emit('save-questions',questionDrafts)"><Save :size="16"/>保存测试集</button></footer></main><main v-else class="gold-empty">暂无数据，可生成配套样例或上传资料。</main>
  </div>
 </section></div></Teleport>
</template>
<style scoped>
.gold-manager-mask{position:fixed;inset:0;z-index:3200;background:#25163866;display:flex;align-items:center;justify-content:center;padding:24px;backdrop-filter:blur(5px)}.gold-manager{width:min(1240px,100%);height:min(860px,94vh);background:#fff;border-radius:24px;display:flex;flex-direction:column;box-shadow:0 24px 80px #27163b33;color:#5a426e}.gold-manager header{display:flex;align-items:center;gap:16px;padding:24px 28px;border-bottom:1px solid #eee6f5}.gold-manager h2{margin:0;font-size:23px}.gold-manager header p{color:#9d89ac;margin:7px 0 0;font-size:13px}.gold-manager header>button{margin-left:auto}.gold-manager-icon{padding:15px;background:#f3ebff;color:#7c3aed;border-radius:16px}.gold-manager button{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:10px 13px;border:1px solid #e6dbf2;border-radius:11px;background:#fff;color:#8059a2;cursor:pointer;font:inherit;font-size:13px}.gold-manager button:hover{background:#f3edfc}.gold-manager button:disabled{opacity:.5;cursor:default}.gold-manager-body{display:grid;grid-template-columns:320px 1fr;min-height:0;flex:1}.gold-manager aside{overflow:auto;padding:20px;background:#fcfaff;border-right:1px solid #eee6f5}.gold-manager-search{display:flex;gap:8px;align-items:center;padding:10px;background:#fff;border:1px solid #e5d9f1;border-radius:12px;margin-bottom:15px}.gold-manager-search input{border:0;background:none;min-width:0;width:100%;outline:none}.gold-manager .gold-item{display:flex;flex-direction:column;align-items:flex-start;text-align:left;width:100%;margin:9px 0;padding:14px;gap:7px}.gold-item small,.gold-item span{font-size:11px;color:#a188b5}.gold-item strong{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.gold-manager .selected{background:#efe4fc;border-color:#c5a7eb}.gold-manager main{overflow:auto;padding:25px 30px}.gold-manager label{display:block;margin-bottom:20px;font-size:13px;font-weight:600}.gold-manager input,.gold-manager textarea,.gold-manager select{box-sizing:border-box;font:inherit;color:#51435d;width:100%;padding:13px;border:1px solid #dfd4eb;border-radius:12px;margin-top:9px;line-height:1.8;background:#fff}.gold-manager textarea{resize:vertical;font-weight:400}.gold-manager nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}.gold-manager footer{display:flex;justify-content:flex-end;gap:12px;padding:15px 0;position:sticky;bottom:-25px;background:#fff}.gold-manager .gold-primary{background:#7c3aed;color:#fff;border-color:#7c3aed}.gold-note{font-size:12px;line-height:1.8;color:#a087b1}.gold-evidence{padding:13px;border-radius:12px;background:#faf7ff;font-size:12px;line-height:1.9;white-space:pre-wrap}.gold-empty{color:#a087b1}@media(max-width:800px){.gold-manager-mask{padding:10px}.gold-manager-body{grid-template-columns:1fr}.gold-manager aside{max-height:200px;border-bottom:1px solid #eee6f5}.gold-manager main{padding:18px}}
.gold-manager-error{margin:12px 28px 0;padding:12px;border-radius:10px;background:#fff0f3;color:#b44460;font-size:13px}</style>
